package com.nvv.mediadata.data.viewmodelimport androidx.lifecycle.ViewModelimport dagger.hilt.android.lifecycle.HiltViewModelimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.asStateFlowimport javax.inject.Inject@HiltViewModelclass NotificationViewModel @Inject constructor() : ViewModel() {	private var _isOpen = MutableStateFlow(false)	val isOpen = _isOpen.asStateFlow()	private var _message = MutableStateFlow("")	val message = _message.asStateFlow()	fun open(message: String) {		_isOpen.value = true		_message.value = message	}	fun close() {		_isOpen.value = false		_message.value = ""	}}